// js/dashboard.js — Shahapur GIS Dashboard
//
// Every number on this page is computed from the real data files generated by
// scripts/build_data.py (Excel register + tagged footprints + photo/plan index).
// Infrastructure counts (poles, bridges, ...) exist only on the MRSAC MapServer, so
// they are shown when that service answers and as "—" when it does not.

console.log('[Shahapur GIS - Dashboard] Loading dashboard.js module...');

let activeDashboardCharts = [];
const DB_WARDS = ['1', '2', '3', '4', '5'];
const DB_MAPSERVER_URL = "https://gsc.mrsac.org.in/webadpgis2/rest/services/test/Test2/MapServer";
const DB_LIVE_LAYERS = [
  { id: 10, key: 'poles', label: 'Street light poles', icon: 'ph-lightbulb' },
  { id: 13, key: 'solar', label: 'Solar panels', icon: 'ph-sun' },
  { id: 1, key: 'bridges', label: 'Bridges', icon: 'ph-bridge' },
  { id: 4, key: 'electric', label: 'Electric line segments', icon: 'ph-lightning' },
  { id: 7, key: 'roads', label: 'Kutcha road segments', icon: 'ph-path' },
  { id: 5, key: 'fencing', label: 'Fencing segments', icon: 'ph-grid-four' }
];

const dbEsc = v => String(v === null || v === undefined ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const dbNum = n => Number(n || 0).toLocaleString('en-IN');
const dbPct = (a, b) => (b ? (a / b * 100) : 0).toFixed(1);
const dbLakh = n => '₹' + (Number(n || 0) / 100000).toFixed(2) + 'L';

/** Aggregate register units (optionally for one ward). */
function computeDashboardStats(wardNo) {
  const all = (window.TaxDataService ? window.TaxDataService.getAll() : window.SHAHAPUR_TAX_DATA) || [];
  const units = (!wardNo || wardNo === 'All') ? all : all.filter(u => String(u.wardNo) === String(wardNo));
  const buildings = ((window.SHAHAPUR_BUILDINGS_DATA || {}).features || [])
    .filter(f => !wardNo || wardNo === 'All' || f.properties.wardNo === String(wardNo));

  const s = {
    units: units.length,
    properties: new Set(units.map(u => u.wardNo + '-' + u.propertyNo)).size,
    footprints: buildings.length,
    taggedFootprints: buildings.filter(f => f.properties.unitsCount > 0).length,
    assessed: 0, assessedCount: 0, rv: 0,
    withPhoto: 0, withPlan: 0, mapped: 0,
    water: 0, borewell: 0, solar: 0, rain: 0, lift: 0,
    usage: {}, top: []
  };
  units.forEach(u => {
    s.assessed += Number(u.assessedAmount || 0);
    s.rv += Number(u.rvOld || 0);
    if (u.status === 'Assessed') s.assessedCount++;
    if (u.photos && u.photos.length) s.withPhoto++;
    if ((u.plans && u.plans.length) || u.plan) s.withPlan++;
    if (u.buildingIds && u.buildingIds.length) s.mapped++;
    if (u.waterConnection === 'Yes') s.water++;
    if (u.borewell === 'Yes') s.borewell++;
    if (u.solar === 'Yes') s.solar++;
    if (u.rainwaterHarvesting === 'Yes') s.rain++;
    if (u.lift === 'Yes') s.lift++;
    const use = u.description || 'Not recorded';
    s.usage[use] = (s.usage[use] || 0) + 1;
  });
  s.top = [...units].sort((a, b) => (b.assessedAmount || 0) - (a.assessedAmount || 0)).slice(0, 5);
  return s;
}

