function currentDashboardWard() {
  const sel = document.getElementById('db-ward-filter');
  return sel ? sel.value : 'All';
}

/** Fill KPI cards, register card, ward list and top list for the selected ward. */
function updateDashboardStats() {
  const ward = currentDashboardWard();
  const s = computeDashboardStats(ward);
  const set = (id, html) => { const el = document.getElementById(id); if (el) el.innerHTML = html; };

  const kpi = (icon, color, value, label, sub) => `
    <div class="db-kpi-card">
      <div class="db-kpi-top"><div class="db-kpi-icon ${color}"><i class="ph ${icon}"></i></div></div>
      <div class="db-kpi-val">${value}</div>
      <div class="db-kpi-lbl">${label}</div>
      <div class="db-kpi-sub"><span>${sub}</span></div>
    </div>`;
  set('db-kpis', [
    kpi('ph-buildings', 'blue', dbNum(s.footprints), 'Building footprints', `${dbNum(s.taggedFootprints)} tagged to a property`),
    kpi('ph-door', 'purple', dbNum(s.units), 'Register units', `${dbNum(s.properties)} properties`),
    kpi('ph-map-pin', 'teal', dbPct(s.mapped, s.units) + '%', 'Units on map', `${dbNum(s.mapped)} linked to a footprint`),
    kpi('ph-camera', 'orange', dbPct(s.withPhoto, s.units) + '%', 'Units with photo', `${dbNum(s.withPhoto)} units`),
    kpi('ph-blueprint', 'amber', dbPct(s.withPlan, s.units) + '%', 'Units with plan', `${dbNum(s.withPlan)} units`),
    kpi('ph-drop', 'emerald', dbNum(s.water), 'Water connections', `${dbNum(s.solar)} units with solar`)
  ].join(''));

  set('db-stat-total-tax', dbLakh(s.assessed));
  set('db-tax-strip', `
    <div class="mt-stat"><span class="mt-lbl">Total Tax Demand</span><span class="mt-val">${dbLakh(s.assessed)}</span></div>
    <div class="mt-stat"><span class="mt-lbl">Total Rateable Value</span><span class="mt-val">${dbLakh(s.rv)}</span></div>
    <div class="mt-stat"><span class="mt-lbl">Assessed Units</span><span class="mt-val">${dbNum(s.assessedCount)} <small class="pos">(${dbPct(s.assessedCount, s.units)}%)</small></span></div>
    <div class="mt-stat"><span class="mt-lbl">Unassessed Units</span><span class="mt-val">${dbNum(s.units - s.assessedCount)} <small class="text-muted">(${dbPct(s.units - s.assessedCount, s.units)}%)</small></span></div>
  `);

  set('db-register-card', `
    <div class="db-target-vals">
      <span class="curr">${dbNum(s.assessedCount)} <small class="text-muted" style="font-size:0.7rem; font-weight:500;">(${dbPct(s.assessedCount, s.units)}%)</small></span>
      <span class="tot">${dbNum(s.units)} Total</span>
    </div>
    <div class="db-progress-bg"><div class="db-progress-fill" style="width:${dbPct(s.assessedCount, s.units)}%;"></div></div>
    <div class="target-sub-metrics" style="margin-top:0.65rem;">
      <span><i class="ph ph-check-circle" style="color:#10b981;"></i> ${dbNum(s.assessedCount)} Assessed</span>
      <span><i class="ph ph-info" style="color:#64748b;"></i> ${dbNum(s.units - s.assessedCount)} Unassessed</span>
    </div>`);
  set('db-gauge-rate', dbPct(s.assessedCount, s.units) + '%');
  set('db-fin-grid', `
    <div class="db-fin-stat"><span class="fin-stat-lbl">Tax Demand</span><span class="fin-stat-val">${dbLakh(s.assessed)}</span></div>
    <div class="db-fin-stat"><span class="fin-stat-lbl">Rateable Val</span><span class="fin-stat-val text-success">${dbLakh(s.rv)}</span></div>
    <div class="db-fin-stat"><span class="fin-stat-lbl">Units</span><span class="fin-stat-val">${dbNum(s.units)}</span></div>`);

  const wardTotals = (window.SHAHAPUR_SUMMARY_STATS || {}).wardTotals || {};
  const colors = ['green', 'teal', 'orange', 'blue', 'purple'];
  set('db-ward-list', DB_WARDS.map((w, i) => {
    const t = wardTotals[w] || {};
    const pct = dbPct(t.assessedCount || 0, t.totalProperties || 0);
    return `<div class="rec-item">
      <div class="rec-row"><span>W${w} Prabhag ${w}</span> <span>${dbNum(t.assessedCount)} / ${dbNum(t.totalProperties)} <b>(${pct}%)</b> • ${dbLakh(t.totalAssessed)}</span></div>
      <div class="rec-bar-bg"><div class="rec-bar-fill ${colors[i]}" style="width:${pct}%;"></div></div>
    </div>`;
  }).join(''));

  set('db-top-scope', ward === 'All' ? 'All wards' : `Ward ${dbEsc(ward)}`);
  set('db-top-list', s.top.map(u => `
    <div class="tx-item" style="cursor:pointer;" onclick="window.viewPropertyAssessmentModal && window.viewPropertyAssessmentModal(${Number(u.propertyId)})">
      <div class="tx-icon blue"><i class="ph ph-buildings"></i></div>
      <div class="tx-details">
        <div class="name">${dbEsc(u.ownerName || u.shopBuildingName || 'Owner not recorded')}</div>
        <div class="time">Ward ${dbEsc(u.wardNo)} • Prop ${dbEsc(u.propertyNo)}${u.partitionNo ? '/' + dbEsc(u.partitionNo) : ''}${u.description ? ' • ' + dbEsc(u.description) : ''}</div>
      </div>
      <div class="tx-amount pos">₹${dbNum(u.assessedAmount)} <span class="sub">Demand</span></div>
    </div>`).join('') || '<div class="text-muted" style="padding:1rem;">No assessed units.</div>');
}

/** Infrastructure counts exist only on the MRSAC MapServer; nothing is shown if it is down. */
function queryMapServerCounts() {
  const ward = currentDashboardWard();
  const statusEl = document.getElementById('db-live-status');
  DB_LIVE_LAYERS.forEach(l => { const el = document.getElementById(`db-live-${l.key}`); if (el) el.textContent = '—'; });
  if (typeof require !== 'function') return;

  require(["esri/rest/query", "esri/rest/support/Query"], (query, Query) => {
    let ok = 0, failed = 0;
    const done = () => {
      if (!statusEl || ok + failed < DB_LIVE_LAYERS.length) return;
      statusEl.textContent = ok
        ? `Live counts from MRSAC MapServer${ward !== 'All' ? ' (whole council; layers have no ward field)' : ''}`
        : 'MapServer unavailable — no infrastructure data to show';
    };
    DB_LIVE_LAYERS.forEach(l => {
      query.executeForCount(`${DB_MAPSERVER_URL}/${l.id}`, new Query({ where: '1=1' }))
        .then(count => {
          const el = document.getElementById(`db-live-${l.key}`);
          if (el && typeof count === 'number') el.textContent = dbNum(count);
          ok++; done();
        })
        .catch(err => {
          console.warn(`[Shahapur GIS - Dashboard] MapServer layer ${l.id} count failed:`, err.message || err);
          failed++; done();
        });
    });
  });
}

function buildDashboardCharts() {
  if (typeof Chart === 'undefined') {
    console.warn('[Shahapur GIS - Dashboard] Chart.js is not loaded on window.');
    return;
  }
  try {
    Chart.defaults.font.family = "'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif";
    Chart.defaults.font.size = 10;
    Chart.defaults.color = '#64748b';

    activeDashboardCharts.forEach(c => c && c.destroy && c.destroy());
    activeDashboardCharts = [];
    const add = (id, config) => {
      const el = document.getElementById(id);
      if (!el) return;
      const existing = Chart.getChart && Chart.getChart(el);
      if (existing) existing.destroy();
      activeDashboardCharts.push(new Chart(el.getContext('2d'), config));
    };
    const legendBottom = { position: 'bottom', labels: { boxWidth: 8, font: { size: 9.5, weight: '600' }, color: '#475569', padding: 6 } };
    const gridY = { grid: { color: 'rgba(241, 245, 249, 0.8)' }, ticks: { font: { size: 9.5 } } };
    const gridX = { grid: { display: false }, ticks: { font: { size: 9.5, weight: 600 } } };
    const wardLabels = DB_WARDS.map(w => `Ward ${w}`);
    const stats = window.SHAHAPUR_SUMMARY_STATS || {};
    const wt = stats.wardTotals || {};
    const perWard = DB_WARDS.map(w => computeDashboardStats(w));
    const scoped = computeDashboardStats(currentDashboardWard());

    // 1. Ward tax demand & rateable value (₹ lakh)
    add('chart-monthly-tax', {
      type: 'bar',
      data: {
        labels: wardLabels,
        datasets: [
          { label: 'Tax Demand (₹ Lakh)', data: DB_WARDS.map(w => +((wt[w]?.totalAssessed || 0) / 1e5).toFixed(2)), backgroundColor: '#10b981', borderRadius: 5, maxBarThickness: 36, yAxisID: 'y' },
          { label: 'Rateable Value (₹ Lakh)', data: DB_WARDS.map(w => +((wt[w]?.totalRateableValue || 0) / 1e5).toFixed(2)), backgroundColor: '#0284c7', borderRadius: 5, maxBarThickness: 36, yAxisID: 'y1' }
        ]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { display: false }, tooltip: { callbacks: { label: c => ` ${c.dataset.label}: ₹${c.parsed.y}L` } } },
        scales: {
          x: gridX,
          y: { position: 'left', ...gridY, ticks: { color: '#10b981', callback: v => '₹' + v + 'L' } },
          y1: { position: 'right', grid: { display: false }, ticks: { color: '#0284c7', callback: v => '₹' + v + 'L' } }
        }
      }
    });

    // 2. Usage donut (top 5 categories + other) for the selected ward
    const usage = Object.entries(scoped.usage).sort((a, b) => b[1] - a[1]);
    const topUsage = usage.slice(0, 5);
    const otherCount = usage.slice(5).reduce((n, [, c]) => n + c, 0);
    if (otherCount) topUsage.push(['Other', otherCount]);
    const usageColors = ['#6366f1', '#0ea5e9', '#10b981', '#f59e0b', '#8b5cf6', '#94a3b8'];
    add('chart-landuse', {
      type: 'doughnut',
      data: { labels: topUsage.map(u => u[0]), datasets: [{ data: topUsage.map(u => u[1]), backgroundColor: usageColors, borderWidth: 2, borderColor: '#ffffff' }] },
      options: { responsive: true, maintainAspectRatio: false, cutout: '72%', plugins: { legend: { display: false } } }
    });
    const totalEl = document.getElementById('db-usage-total');
    if (totalEl) totalEl.textContent = dbNum(scoped.units);
    const legendEl = document.getElementById('db-usage-legend');
    if (legendEl) {
      legendEl.innerHTML = topUsage.map(([name, n], i) =>
        `<div class="donut-leg-item"><span class="dot" style="background:${usageColors[i]};"></span> ${dbEsc(name)} <b>${dbPct(n, scoped.units)}%</b></div>`).join('');
    }

    // 3. Usage by ward (stacked, 3 most common categories council-wide + other)
    const councilUsage = Object.entries(stats.descriptionCounts || {}).sort((a, b) => b[1] - a[1]).slice(0, 3).map(u => u[0]);
    const wardUsage = stats.wardUsage || {};
    add('chart-building-class', {
      type: 'bar',
      data: {
        labels: wardLabels,
        datasets: [
          ...councilUsage.map((name, i) => ({ label: name, data: DB_WARDS.map(w => (wardUsage[w] || {})[name] || 0), backgroundColor: usageColors[i], borderRadius: 4, maxBarThickness: 32 })),
          { label: 'Other', data: DB_WARDS.map(w => Object.entries(wardUsage[w] || {}).filter(([k]) => !councilUsage.includes(k)).reduce((n, [, c]) => n + c, 0)), backgroundColor: '#cbd5e1', borderRadius: 4, maxBarThickness: 32 }
        ]
      },
      options: { responsive: true, maintainAspectRatio: false, plugins: { legend: legendBottom }, scales: { x: { stacked: true, ...gridX }, y: { stacked: true, ...gridY } } }
    });

    // 4. Assessment gauge
    add('chart-fin-gauge', {
      type: 'doughnut',
      data: { labels: ['Assessed', 'Unassessed'], datasets: [{ data: [scoped.assessedCount, scoped.units - scoped.assessedCount], backgroundColor: ['#10b981', '#e2e8f0'], borderWidth: 0, circumference: 180, rotation: 270 }] },
      options: { responsive: true, maintainAspectRatio: false, cutout: '80%', plugins: { legend: { display: false } } }
    });

    // 5. Civic amenities by ward
    const amenity = (label, key, color) => ({ label, data: perWard.map(s => s[key]), backgroundColor: color, borderRadius: 3, maxBarThickness: 14 });
    add('chart-amenities', {
      type: 'bar',
      data: { labels: wardLabels, datasets: [
        amenity('Water', 'water', '#0ea5e9'), amenity('Borewell', 'borewell', '#6366f1'),
        amenity('Solar', 'solar', '#f59e0b'), amenity('Rainwater', 'rain', '#10b981'), amenity('Lift', 'lift', '#64748b')
      ] },
      options: { responsive: true, maintainAspectRatio: false, plugins: { legend: legendBottom }, scales: { x: gridX, y: gridY } }
    });

    // 6. Data linkage coverage by ward (%)
    const pctSet = (label, key, color) => ({ label, data: perWard.map(s => +dbPct(s[key], s.units)), backgroundColor: color, borderRadius: 3, maxBarThickness: 16 });
    add('chart-linkage', {
      type: 'bar',
      data: { labels: wardLabels, datasets: [pctSet('Photo', 'withPhoto', '#f59e0b'), pctSet('Plan', 'withPlan', '#0284c7'), pctSet('On map', 'mapped', '#10b981')] },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: legendBottom, tooltip: { callbacks: { label: c => ` ${c.dataset.label}: ${c.parsed.y}%` } } },
        scales: { x: gridX, y: { ...gridY, min: 0, max: 100, ticks: { callback: v => v + '%' } } }
      }
    });
    console.info('[Shahapur GIS - Dashboard] Rendered', activeDashboardCharts.length, 'charts from register data.');
  } catch (err) {
    console.error("[Shahapur GIS - Dashboard] Error rendering dashboard charts:", err);
  }
}

// Dedicated Mini-Map View in Spatial Overview
let dbMiniMapView = null;

function initDashboardMiniMap() {
  const mount = document.getElementById('db-mini-map-view');
  if (!mount) {
    console.log('[Shahapur GIS - Dashboard] #db-mini-map-view not present in DOM, skipping mini-map.');
    return;
  }

  // Defer slightly if ArcGIS require is not yet ready
  if (typeof require === 'undefined') {
    console.log('[Shahapur GIS - Dashboard] require() not ready for mini-map, retrying in 150ms...');
    setTimeout(initDashboardMiniMap, 150);
    return;
  }

  console.log('[Shahapur GIS - Dashboard] Initializing Dashboard mini-map...');
  require([
    "esri/Map",
    "esri/views/MapView",
    "esri/layers/FeatureLayer",
    "esri/Graphic",
    "esri/geometry/Polygon"
  ], (Map, MapView, FeatureLayer, Graphic, Polygon) => {
    // If view already attached to this container, skip rebuild
    if (dbMiniMapView && dbMiniMapView.container === mount) {
      console.log('[Shahapur GIS - Dashboard] Mini-map already mounted to container.');
      return;
    }
    if (dbMiniMapView && typeof dbMiniMapView.destroy === 'function') {
      try { 
        console.log('[Shahapur GIS - Dashboard] Destroying previous mini-map view...');
        dbMiniMapView.destroy(); 
      } catch(e) {}
      dbMiniMapView = null;
    }

    const layers = [];

    // Client-side Council Boundary
    if (window.SHAHAPUR_COUNCIL_DATA && window.SHAHAPUR_COUNCIL_DATA.features) {
      const councilGraphics = window.SHAHAPUR_COUNCIL_DATA.features.map(f => new Graphic({
        geometry: new Polygon({ rings: f.geometry.coordinates, spatialReference: { wkid: 4326 } }),
        attributes: f.properties
      }));
      layers.push(new FeatureLayer({
        source: councilGraphics,
        objectIdField: "OBJECTID",
        opacity: 0.95,
        title: "Council Boundary",
        renderer: {
          type: "simple",
          symbol: { type: "simple-fill", color: [10, 66, 89, 0.08], outline: { color: "#0A4259", width: 2 } }
        }
      }));
    }

    // Client-side Ward Boundary
    if (window.SHAHAPUR_WARDS_DATA && window.SHAHAPUR_WARDS_DATA.features) {
      const wardGraphics = window.SHAHAPUR_WARDS_DATA.features.map(f => new Graphic({
        geometry: new Polygon({ rings: f.geometry.coordinates, spatialReference: { wkid: 4326 } }),
        attributes: f.properties
      }));
      layers.push(new FeatureLayer({
        source: wardGraphics,
        objectIdField: "OBJECTID",
        opacity: 0.85,
        title: "Ward Boundary",
        renderer: {
          type: "simple",
          symbol: { type: "simple-fill", color: [0, 180, 216, 0.08], outline: { color: "#00B4D8", width: 2 } }
        }
      }));
    }

    const miniMap = new Map({
      basemap: "hybrid",
      layers: layers
    });

    dbMiniMapView = new MapView({
      container: mount,
      map: miniMap,
      center: [73.3265, 19.4538],
      zoom: 13.8,
      ui: { components: [] },
      constraints: {
        rotationEnabled: false,
        minZoom: 11,
        maxZoom: 18
      }
    });

    console.info('[Shahapur GIS - Dashboard] Mini MapView created for Shahapur.');

    // Prevent vertical page scroll interruption
    dbMiniMapView.on("mouse-wheel", (evt) => {
      evt.stopPropagation();
    });

    // Real-time cursor coordinates
    dbMiniMapView.on("pointer-move", (evt) => {
      const pt = dbMiniMapView.toMap({ x: evt.x, y: evt.y });
      if (pt) {
        const coordsEl = document.getElementById('mini-map-coords');
        if (coordsEl) {
          coordsEl.textContent = `${pt.latitude.toFixed(4)}°N, ${pt.longitude.toFixed(4)}°E`;
        }
      }
    });

    // Mini Zoom Controls
    const btnZoomIn = document.getElementById('btn-mini-zoom-in');
    const btnZoomOut = document.getElementById('btn-mini-zoom-out');
    const btnRecenter = document.getElementById('btn-mini-recenter');

    if (btnZoomIn) {
      btnZoomIn.onclick = (e) => {
        e.stopPropagation();
        dbMiniMapView.goTo({ zoom: dbMiniMapView.zoom + 1 }, { duration: 250 });
      };
    }
    if (btnZoomOut) {
      btnZoomOut.onclick = (e) => {
        e.stopPropagation();
        dbMiniMapView.goTo({ zoom: dbMiniMapView.zoom - 1 }, { duration: 250 });
      };
    }
    if (btnRecenter) {
      btnRecenter.onclick = (e) => {
        e.stopPropagation();
        console.log('[Shahapur GIS - Dashboard] Mini-map recenter clicked.');
        dbMiniMapView.goTo({ center: [73.3265, 19.4538], zoom: 13.8 }, { duration: 400 });
        document.querySelectorAll('.spatial-pill').forEach(p => p.classList.remove('active'));
        document.querySelector('.spatial-pill[data-ward="All"]')?.classList.add('active');
      };
    }

    // Ward extents come from the ward outlines in data/wardsData.js
    const toPolygon = f => new Polygon({ rings: f.geometry.coordinates, spatialReference: { wkid: 4326 } });
    const WARD_EXTENTS = { 'All': { center: [73.3265, 19.4538], zoom: 13.8 } };
    const council = ((window.SHAHAPUR_COUNCIL_DATA || {}).features || [])[0];
    if (council) WARD_EXTENTS['All'] = { target: toPolygon(council) };
    ((window.SHAHAPUR_WARDS_DATA || {}).features || []).forEach(f => {
      WARD_EXTENTS[f.properties.Ward_No] = { target: toPolygon(f) };
    });

    document.querySelectorAll('.spatial-pill').forEach(pill => {
      pill.onclick = (e) => {
        e.stopPropagation();
        document.querySelectorAll('.spatial-pill').forEach(p => p.classList.remove('active'));
        pill.classList.add('active');
        const wardKey = pill.getAttribute('data-ward');
        console.log('[Shahapur GIS - Dashboard] Mini-map spatial pill clicked for Ward:', wardKey);
        const target = WARD_EXTENTS[wardKey] || WARD_EXTENTS['All'];
        dbMiniMapView.goTo(target.target || target, { duration: 500 }).catch(() => {});
      };
    });
  });
}

// Router Event Listeners for Dashboard initialization
window.addEventListener('hashchange', () => {
  if (window.location.hash === '#/dashboard' || window.location.hash === '' || window.location.hash === '#/') {
    console.log('[Shahapur GIS - Dashboard] Hash changed to dashboard, rendering...');
    window.renderDashboard();
  }
});

if (window.location.hash === '#/dashboard' || window.location.hash === '' || window.location.hash === '#/') {
  console.log('[Shahapur GIS - Dashboard] Initial route matches dashboard, scheduling render...');
  setTimeout(() => {
    window.renderDashboard();
  }, 150);
}
